'use strict';
const BASE='https://www.brooklyn.edu/admissions-aid/';
const knowledge=[
{id:'apply',title:'Your first step starts here.',terms:/\b(apply|application|first.year|freshman|freshmen|start|admission requirements)\b/i,body:'Apply to Brooklyn College through the CUNY application. Choose Brooklyn College and the correct applicant type.\n\nFor first-year admission, your high school academic preparation is central to the review. Prepare your official high school transcript or high school equivalency documentation, and follow the application’s instructions for supporting materials.\n\nYour next step: open the official first-year requirements page and review the current checklist before submitting.',url:BASE+'first-year/how-to-apply/requirements-and-deadlines/',source:'First-year application requirements',follow:['What are the application deadlines?','What are the transfer requirements?']},
{id:'deadlines',title:'A little planning goes a long way.',terms:/\b(deadline|deadlines|date|dates|when|fall|spring)\b/i,body:'Brooklyn College lists these general first-year and transfer priority deadlines:\n\nFall semester: February 1\nSpring semester: September 15\n\nApplications after the priority deadline are processed on a rolling basis. Special programs may have different timelines. Confirm the current dates and availability on the official page before making plans.',url:BASE+'first-year/how-to-apply/requirements-and-deadlines/',source:'Official application deadlines',follow:['How do I apply as a first-year student?','How can I contact admissions?']},
{id:'transfer',title:'Bring your experience. Keep moving forward.',terms:/\b(transfer|transferring|credits|gpa|community college)\b/i,body:'The current transfer requirements page lists a minimum cumulative GPA of 2.30 for applicants with 12 or more completed credits. Applicants with fewer than 12 credits also need to meet first-year requirements.\n\nApplicants with an A.A. or A.S. from a CUNY community college, or a bachelor’s degree from an accredited institution, have a listed minimum GPA of 2.00.\n\nCredit acceptance depends on an official evaluation; this guide cannot determine your individual eligibility or award transfer credits.',url:BASE+'transfer/how-to-apply/requirements-and-deadlines/',source:'Transfer requirements and deadlines',follow:['What are the application deadlines?','How can I contact admissions?']},
{id:'aid',title:'Let’s explore how to make it possible.',terms:/\b(aid|fafsa|scholarship|scholarships|tuition|cost|pay|paying|fees|afford|money|financial)\b/i,body:'Start with Brooklyn College’s financial aid and scholarship resources. The admissions site recommends completing the FAFSA to explore available financial support.\n\nCosts and eligibility depend on factors such as residency, enrollment, and your circumstances. Use the official tuition and financial aid links on the admissions site for current amounts and requirements.\n\nFor a personal estimate or an eligibility question, contact the college’s financial aid team.',url:BASE,source:'Admissions & financial aid resources',follow:['How do I apply as a first-year student?','How can I contact admissions?']},
{id:'international',title:'Your Brooklyn journey can start anywhere.',terms:/\b(international|visa|toefl|ielts|foreign|f.1|abroad)\b/i,body:'Brooklyn College provides a separate international applicant pathway. Start on the official Apply page and choose International Students to review the appropriate application and documentation requirements.\n\nRequirements can depend on where you studied and your applicant type. Ask admissions to confirm your transcript, translation, and English proficiency requirements. For visa or immigration questions, consult the college’s international student advisers.',url:BASE+'take-the-next-step/apply/',source:'Official application pathways',follow:['What are the application deadlines?','How can I contact admissions?']},
{id:'major',title:'Find a subject that feels like you.',terms:/\b(major|majors|program|programs|study|degree|career|computer|business|psychology)\b/i,body:'Explore the academic program and personalized viewbook options on Brooklyn College’s admissions pages. Think about the subjects you enjoy, skills you want to develop, and possible career paths.\n\nFor a specific major, review its official department page and ask an adviser about any additional requirements. The admissions team can help you find the right department.',url:BASE+'first-year/',source:'Explore Brooklyn College',follow:['How do I apply as a first-year student?','Can I visit campus?']},
{id:'visit',title:'Get a feel for your future campus.',terms:/\b(visit|tour|campus|location|address|open house)\b/i,body:'Explore campus tour and admissions event options on Brooklyn College’s admissions pages. Check the current schedule and register through the official event links.\n\nBrooklyn College is at 2900 Bedford Avenue, Brooklyn, NY 11210. The Office of Undergraduate Admissions is listed at 222 West Quad Center.\n\nConfirm availability before traveling to campus.',url:BASE+'transfer/',source:'Campus tours & admissions events',follow:['How can I contact admissions?','How do I apply as a first-year student?']},
{id:'contact',title:'Sometimes, a conversation makes the difference.',terms:/\b(contact|human|person|counselor|email|phone|appointment|office|help|status|decision|accepted|rejected|account)\b/i,body:'For application-specific questions, connect directly with the Office of Undergraduate Admissions. The official admissions page includes appointment options and current contact details.\n\nThis preview cannot access your application, check a decision, or book an appointment for you. Use the official admissions links for personal support, and avoid sharing IDs, passwords, or private documents here.',url:BASE+'first-year/',source:'Contact undergraduate admissions',follow:['What are the application deadlines?','Can I visit campus?']}
];
const $=s=>document.querySelector(s);let saved=[];let pending=false;let currentView='chat';
try{const raw=JSON.parse(localStorage.getItem('bc-saved')||'[]');if(Array.isArray(raw))saved=raw.filter(id=>knowledge.some(k=>k.id===id));}catch{}
const element=(tag,cls,text)=>{const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el;};
function external(url,label,cls){const a=element('a',cls,label+' ↗');a.href=url;a.target='_blank';a.rel='noopener';return a;}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2300);}
function persist(){try{localStorage.setItem('bc-saved',JSON.stringify(saved));}catch{toast('Saved for this visit. Browser storage is unavailable.');}$('#saved-count').textContent=saved.length;}
function setView(view){currentView=view;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#library').hidden=view!=='resources';$('#saved').hidden=view!=='saved';$('#conversation').hidden=view!=='chat'||!$('#conversation').children.length;$('#welcome').hidden=view!=='chat'||!!$('#conversation').children.length;$('#composer-area').hidden=view!=='chat';$('#page-title').textContent={chat:'Admissions assistant',resources:'Resource library',saved:'Saved answers'}[view];$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');if(view==='saved')renderSaved();}
function renderResources(){const root=$('#library');root.replaceChildren(element('h2','', 'Good information. All in one place.'),element('p','', 'Explore official Brooklyn College resources for your next step.'));const grid=element('div','resource-grid');for(const item of knowledge){const card=external(item.url,'','resource');card.replaceChildren(element('h3','',item.source+' ↗'),element('p','',item.body.split('\n')[0]));grid.append(card);}root.append(grid,element('p','disclaimer','Source review: October 6, 2026. Policies can change; check the linked pages for current details.'));}
function renderSaved(){const root=$('#saved');root.replaceChildren(element('h2','','A little clarity, kept for later.'),element('p','','Saved answers stay in this browser.'));if(!saved.length){root.append(element('div','empty-state','No saved answers yet. Ask a question, then select “Save answer.”'));return;}for(const id of saved){const item=knowledge.find(k=>k.id===id);const box=element('article','saved-entry');const remove=element('button','','Remove');remove.onclick=()=>{saved=saved.filter(s=>s!==id);persist();renderSaved();};box.append(remove,element('h3','',item.title),element('p','',item.body),external(item.url,item.source));root.append(box);}}
function resolve(text){if(/\b(hi|hello|hey|thanks|thank you)\b/i.test(text)&&text.split(/\s/).length<5)return {title:'Hi! It’s good to have you here.',body:'I can help you find information about applications, deadlines, transfer requirements, financial aid, and campus visits. What would you like to explore?',follow:['How do I apply as a first-year student?','What financial aid is available?']};const priority=['contact','deadlines','international','transfer','aid','major','visit','apply'];return priority.map(id=>knowledge.find(k=>k.id===id)).find(k=>k.terms.test(text))||{title:'Let’s find the right answer.',body:'I don’t have a verified answer to that question in this curated preview. The undergraduate admissions team is the best next step for a specific or unusual question.\n\nYou can also ask about applying, deadlines, transferring, financial aid, or visiting campus.',url:BASE+'first-year/',source:'Ask undergraduate admissions',follow:['How can I contact admissions?','How do I apply as a first-year student?']};}
function addAnswer(item){const row=element('article','message assistant');row.append(element('div','assistant-icon','✦'));const bubble=element('div','bubble');bubble.append(element('h3','',item.title),element('p','',item.body));if(item.url)bubble.append(external(item.url,item.source,'source-link'));const actions=element('div','message-actions');if(item.id){const save=element('button','',saved.includes(item.id)?'✓ Saved':'♧ Save answer');save.onclick=()=>{if(!saved.includes(item.id)){saved.push(item.id);persist();}save.textContent='✓ Saved';toast('Answer saved in this browser');};actions.append(save);}const copy=element('button','','Copy answer');copy.onclick=async()=>{try{await navigator.clipboard.writeText(item.title+'\n\n'+item.body+(item.url?'\n\nSource: '+item.url:''));toast('Answer copied');}catch{toast('Copy unavailable. Select the answer text to copy it.');}};actions.append(copy);bubble.append(actions);if(item.follow){const follow=element('div','followups');item.follow.forEach(q=>{const btn=element('button','',q+' ↗');btn.onclick=()=>send(q);follow.append(btn);});bubble.append(follow);}row.append(bubble);$('#conversation').append(row);}
async function send(text){text=text.trim();if(!text||pending)return;pending=true;$('#send').disabled=true;$('#new-chat').disabled=true;$('#question').value='';const message=element('article','message user');message.append(element('div','bubble',text.slice(0,1500)));$('#conversation').append(message);setView('chat');addAnswer(resolve(text));pending=false;$('#send').disabled=false;$('#new-chat').disabled=false;$('#composer-area').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'end'});$('#question').focus({preventScroll:true});}
$('#chat-form').addEventListener('submit',e=>{e.preventDefault();send($('#question').value);});$('#question').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();send(e.target.value);}});document.querySelectorAll('[data-prompt]').forEach(b=>b.addEventListener('click',()=>send(b.dataset.prompt)));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#new-chat').onclick=()=>{$('#conversation').replaceChildren();$('#question').value='';setView('chat');$('#question').focus();};$('#menu').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open));};document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');}});document.addEventListener('click',e=>{if(!e.target.closest('#sidebar')&&!e.target.closest('#menu')){$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');}});renderResources();persist();
